import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        while (line.substring(1, line.length() - 1).contains("dot")) {
            int dotPos = line.substring(1).indexOf("dot") + 1;
            line = line.substring(0, dotPos) + "." + line.substring(dotPos + 3);
        }
        int atPos = line.substring(1).indexOf("at") + 1;
        line = line.substring(0, atPos) + "@" + line.substring(atPos + 2);
        System.out.println(line);
        scanner.close();
    }
}
